    "mailadm.cnt": "{m} mailbox(en), {r} regels",
    "settings.tab.email": "E-mail",
    "mailadm.acc_empty": "Nog geen mailbox gekoppeld. Gemachtigde gebruikers slaan hun mailbox zelf op in het gebied <b>E-mail</b> (tegel in het portaal). Toegang: Beveiliging → Rechten, kolom “E-mail”.",
    "mailadm.th_user": "Gebruiker",
