    "mailadm.server_n": "gebruikers met servertoegang",
    "mailadm.accounts_hint": "Wie een mailbox heeft opgeslagen en hoeveel regels er draaien. <b>Inhoud en regelteksten worden hier bewust niet getoond</b> – ze horen bij de betreffende gebruiker.",
    "mail.portal_title": "E-mail",
    "mail.acct_head": "Mijn mailbox",
    "mail.acct_hint": "Sla hier uw eigen Exchange-mailbox op. Het wachtwoord wordt versleuteld bewaard en wordt door geen enkel endpoint teruggegeven – ook niet aan beheerders. Laat het veld leeg om het ongewijzigd te laten.",
    "mail.acct_address": "E-mailadres",
